INSERT INTO `image_texts` (`id`, `unique_id`, `language_id`, `image`, `hero_section_title`, `hero_section_text`, `hero_section_desc`, `hero_section_button_text`, `hero_section_button_url`, `hero_section_video_url`, `features_section_title`, `features_section_subtitle`, `features_section_text`, `features_section_btn_text`, `features_section_btn_url`, `features_section_video_url`, `blog_section_title`, `partner_section_title`, `partner_section_subtitle`, `work_process_section_title`, `template_section_title`, `template_section_subtitle`, `pricing_section_title`, `pricing_section_subtitle`, `featured_shop_section_title`, `featured_shop_section_subtitle`, `testimonial_section_title`, `created_at`, `updated_at`) VALUES
(1, 12345, 176, 'c304b26e7eae4eb618dc73a3f78536b0a5f649f8.png', 'Our Platform, Your Success Icon', 'Build your Online Shop site within minutes', 'Manage products, payments, and sales effortlessly. Everything you need to grow your business is just a click away. Start today and simplify your e-commerce journey.', 'Get Started Now', '/pricing', 'https://www.youtube.com/watch?v=NwelucS1XeM&list=RDNwelucS1XeM&start_radio=1', 'Why To Choose Our Template', 'Bring More Profit With More Features', 'With our platform, you get powerful tools, seamless integrations, and top-notch support to grow your business. We offer reliable performance, user-friendly features, and the flexibility to scale as you do. Choose us for a partner in your success.', 'Signup Now', '/pricing', 'https://www.youtube.com/watch?v=qqob4D3BoZc', 'Our Latest Blog', 'Our Partners', 'Meet our honourable partners', 'How it works ?', 'Creative & User Friendly Design', 'See Our Modern Ecom Store Designs', 'Pricing Plan', 'Choose Your Perfect Ecommerce Plan', 'Our Featured Shops', 'Take a look at the featured shops', 'What Our Customers Are Saying', NULL, '2025-05-14 03:39:42'),
(2, 12345, 179, 'c5b31ec6dd67c7260142577196b62dc79423b3da.png', 'منصتنا رمز نجاحك', 'قم ببناء موقع متجرك الإلكتروني خلال دقائق', 'قم بإدارة المنتجات والمدفوعات والمبيعات بكل سهولة. كل ما تحتاجه لتنمية أعمالك على بعد نقرة واحدة فقط. ابدأ اليوم وبسّط رحلتك في التجارة الإلكترونية.', 'ابدأ الآن', 'https://www.youtube.com/watch?v=NwelucS1XeM&list=RDNwelucS1XeM&start_radio=1', '/pricing', 'لماذا تختار قالبنا؟', 'احصل على المزيد من الأرباح مع المزيد من الميزات', 'مع منصتنا، ستحصل على أدوات قوية وعمليات تكامل سلسة ودعم من الدرجة الأولى لتنمية أعمالك. نحن نقدم أداءً موثوقًا به وميزات سهلة الاستخدام والمرونة للتوسع حسب رغبتك. اخترنا لنكون شريكًا في نجاحك.', 'سجل الآن', '/pricing', 'https://www.youtube.com/watch?v=qqob4D3BoZc', 'أحدث مدوناتنا', 'شركاؤنا', 'تعرف على شركائنا الكرام', 'كيف يعمل؟', 'تصميم إبداعي وسهل الاستخدام', 'شاهد قالبنا الحديث', 'خطة التسعير', 'اختر خطة العمل المثالية لك', 'متاجرنا المميزة', 'قم بإلقاء نظرة على المتاجر المميزة', 'ماذا يقول عملاؤنا', NULL, NULL);
