(8, 176, 'Exclusive Offer', NULL, '92da6631fcd9348a91f207edced9e9aa0fd1d597.png', 'FF4B2B', 0.00, 'Exclusive Member Offer', 'Get up to 40% off in our holiday sale. Don’t miss out on these festive deals!', 'Claim My 40% OFF', 'https://example.com/', 'FF4B2B', NULL, NULL, 600, 2, 2, '2025-03-13 13:03:13', '2025-03-14 00:58:30', 0),
(9, 176, 'Exclusive Offer!', '3cb18faf46ea24529f440d98929f2f303e2a9eeb.png', NULL, NULL, 1.00, 'Hurry, Limited Time Only!', 'Get up to 50% off on selected items. Time is running out—don’t miss out on these amazing deals!', 'Shop Now', 'https://example.com/', 'FF4B2B', NULL, NULL, 700, 3, 4, '2025-03-13 13:07:50', '2025-03-14 00:58:32', 0),
(10, 176, 'VIP Access', 'ea232c8bcbd712b7792cccb24f56f6e0ccceb4f5.png', NULL, '451D53', 1.00, 'Exclusive VIP Access', 'Unlock early access to our latest products and exclusive discounts. Become a VIP today!', 'Join Now', '/pricing', '383838', '2026-06-26', '12:00 PM', 300, 1, 7, '2025-03-13 13:10:36', '2026-05-26 15:22:00', 1),
(11, 179, 'دخول كبار الشخصيات', '732a263b95fb78c180e0d6665f465e52110275ab.png', NULL, '451D53', 1.00, 'وصول VIP الحصري', 'احصل على وصول مبكر لأحدث منتجاتنا وخصومات حصرية. انضم إلى قائمة كبار الشخصيات اليوم!', 'انضم الآن', '/pricing', '383838', '2045-03-09', '12:00 PM', 300, 1, 7, '2025-03-13 14:09:21', '2025-03-13 14:09:21', 1),
(12, 179, 'عرض حصري', NULL, 'c6d583cec7325044466008105d682be475675330.png', 'FF4B2B', 0.00, 'عرض حصري للأعضاء', 'احصل على خصم يصل إلى ٤٠٪ في عروضنا الخاصة بالعطلات. لا تفوت هذه العروض الاحتفالية!', 'اطلب خصم 40%', 'https://example.com/', 'FF4B2B', NULL, NULL, 600, 2, 2, '2025-03-13 14:10:40', '2025-03-13 14:10:40', 1),
(13, 179, 'عرض حصري!', '11ceccbdcf2b859d729a4d37131212192cf35d9f.png', NULL, NULL, 1.00, 'اسرع، لفترة محدودة فقط!', 'احصل على خصم يصل إلى ٥٠٪ على منتجات مختارة. الوقت ينفذ، لا تفوت هذه العروض الرائعة!', 'تسوق الآن', 'https://example.com/', 'FF4B2B', NULL, NULL, 700, 3, 4, '2025-03-13 14:11:52', '2025-03-13 14:11:52', 1);
INSERT INTO `processes` (`id`, `language_id`, `icon`, `color`, `title`, `text`, `serial_number`) VALUES
(17, 176, 'fas fa-box-open', '9013FE', 'Add Products', 'Upload new products with descriptions, prices, and images to expand your offerings and attract customers.', 5),
(19, 176, 'fas fa-cogs', 'F5A623', 'Setup Store', 'Upload product details, images, and prices to create an appealing store that attracts potential customers.', 3),
(20, 176, 'fas fa-palette', '50E3C2', 'Choose Theme', 'Select a visually appealing theme to personalize your website and enhance the user experience.', 2),
(21, 176, 'fas fa-credit-card', '4A90E2', 'Purchase Subscription', 'Select a plan that fits your needs and get access to exclusive features.', 1),
(23, 176, 'fas fa-university', 'F8E71C', 'Set Payment Methods', 'Enable various payment options to ensure smooth and secure transactions for your customers.', 6),
(24, 176, 'fas fa-hand-holding-usd', 'D0021B', 'Sell Products', 'List your products with detailed descriptions and prices to start selling and attract potential buyers.', 7),
(25, 176, 'fas fa-chart-line', '7ED321', 'Manage Orders', 'Track, process, and update customer orders efficiently to ensure timely fulfillment and satisfaction.', 8),
(26, 176, 'far fa-money-bill-alt', '9013FE', 'Set Currencies', 'Add and configure multiple currencies to provide a seamless shopping experience for customers worldwide.', 4),
(35, 179, 'fas fa-box-open', '9013FE', 'إضافة المنتجات', 'قم بتحميل المنتجات الجديدة مع الأوصاف والأسعار والصور لتوسيع عروضك وجذب العملاء.', 5),
(36, 179, 'fas fa-cogs', 'F5A623', 'إعداد المتجر', 'قم بتحميل تفاصيل المنتج والصور والأسعار لإنشاء متجر جذاب يجذب العملاء المحتملين.', 3),
(37, 179, 'fas fa-palette', '50E3C2', 'اختر الموضوع', 'قم باختيار مظهر جذاب بصريًا لتخصيص موقع الويب الخاص بك وتعزيز تجربة المستخدم.', 2),
(38, 179, 'fas fa-credit-card', '4A90E2', 'شراء الاشتراك', 'اختر الخطة التي تناسب احتياجاتك واحصل على ميزات حصرية.', 1),
(39, 179, 'fas fa-university', 'F8E71C', 'تعيين طرق الدفع', 'قم بتمكين خيارات الدفع المتنوعة لضمان معاملات سلسة وآمنة لعملائك.', 6),
(40, 179, 'fas fa-hand-holding-usd', 'D0021B', 'بيع المنتجات', 'قم بإدراج منتجاتك مع وصف تفصيلي وأسعار لبدء البيع وجذب المشترين المحتملين.', 7),
(41, 179, 'fas fa-chart-line', '7ED321', 'إدارة الطلبات', 'تتبع طلبات العملاء ومعالجتها وتحديثها بكفاءة لضمان الوفاء بها ورضا العملاء في الوقت المناسب.', 8),
(42, 179, 'far fa-money-bill-alt', '9013FE', 'تعيين العملات', 'قم بإضافة وتكوين عملات متعددة لتوفير تجربة تسوق سلسة للعملاء في جميع أنحاء العالم.', 4);
