INSERT INTO `user_about_testimonials` (`id`, `user_id`, `language_id`, `image`, `name`, `designation`, `color`, `rating`, `comment`, `created_at`, `updated_at`) VALUES
(1, 10, 15, '73e671958c872be3bbe79d770e53e8fc1d0d2624.png', 'Ahmed Al-Farsi', 'Business Consultant', 'FFF5F5', 5, 'I’ve been a regular shopper here for months, and I am never disappointed. The quality of the fresh produce and meats is always top-notch, and the prices are very reasonable. The staff is incredibly helpful and friendly.', '2024-11-14 09:27:42', '2024-11-14 09:29:33'),
(2, 10, 16, '0e66ba6d9249f8fd5f5b62ff952c33663fb3cc3a.png', 'احمد الفارسي', 'مستشار الأعمال', 'FFF5F5', 5, 'كنت زبونًا منتظمًا هنا لعدة أشهر، ولم أكن يومًا خائب الأمل. جودة المنتجات الطازجة واللحوم دائمًا من الدرجة الأولى، والأسعار معقولة للغاية. الموظفون متعاونون وودودون بشكل لا يصدق.', '2024-11-14 09:29:14', '2024-11-14 09:29:43'),
(3, 10, 15, '1b9529a23e497480863029ee8b6bf8b1ede74eff.png', 'Omar Khaled', 'Engineer', 'F5FFF9', 5, 'This grocery shop offers the best variety in town. I can always find everything I need, whether it\'s everyday essentials or special ingredients. The store is well-organized and clean. Great shopping experience!', '2024-11-14 09:32:05', '2024-11-14 09:32:05'),
(4, 10, 15, '512e2ee67a9c440cab329bc3a9c885eb6caa164b.png', 'Faisal Al-Mansoori', 'IT Specialist', 'FAF5FF', 4, 'Good prices and a great selection of products. I always find what I need, but I wish there were more variety in the snacks section. Overall, I’m very satisfied with the quality and service.', '2024-11-14 09:33:19', '2024-11-14 09:33:19'),
(5, 10, 16, 'a66109282e217c18b1e35bb76485073778f237eb.png', 'عمر خالد', 'مهندس', 'F5FFF9', 5, 'يقدم متجر البقالة هذا أفضل مجموعة متنوعة في المدينة. يمكنني دائما العثور على كل ما أحتاجه ، سواء كان ذلك من الضروريات اليومية أو المكونات الخاصة. المتجر منظم جيدا ونظيف. تجربة تسوق رائعة!', '2024-11-14 09:35:11', '2024-11-14 09:35:11'),
(6, 10, 16, '039110bb8ab3dff5fb2388a38501739918d0d679.png', 'فيصل المنصوري', 'أخصائي تكنولوجيا المعلومات', 'FAF5FF', 4, 'أسعار جيدة ومجموعة كبيرة من المنتجات. أجد دائما ما أحتاجه ، لكنني أتمنى أن يكون هناك المزيد من التنوع في قسم الوجبات الخفيفة. بشكل عام ، أنا راض جدا عن الجودة والخدمة.', '2024-11-14 09:36:08', '2024-11-14 09:36:08'),
(7, 13, 21, '444f5f1edd3a82e28263a8c8f6a3896fc6279239.png', 'Ahmed Al-Farsi', 'Business Consultant', 'FFF5F5', 5, 'I’ve been a regular shopper here for months, and I am never disappointed. The quality of the fresh produce and meats is always top-notch, and the prices are very reasonable. The staff is incredibly helpful and friendly.', '2024-11-17 05:32:19', '2024-11-17 05:32:19'),
(8, 13, 21, '6cebef31a4b285ebd0674fa0c6899db891f5a13c.png', 'Omar Khaled', 'Engineer', 'F5FFF9', 5, 'This grocery shop offers the best variety in town. I can always find everything I need, whether it\'s everyday essentials or special ingredients. The store is well-organized and clean. Great shopping experience!', '2024-11-17 05:32:46', '2024-11-17 05:32:46'),
(9, 13, 21, '7da14b3f23af8bc5dc03dc73ee82885734c476e1.png', 'Faisal Al-Mansoori', 'IT Specialist', 'FAF5FF', 4, 'Good prices and a great selection of products. I always find what I need, but I wish there were more variety in the snacks section. Overall, I’m very satisfied with the quality and service.', '2024-11-17 05:33:10', '2024-11-17 05:33:10'),
(10, 13, 22, 'd24492ca5ca08ff88c08e639b0e36e4248a7ffbc.png', 'احمد الفارسي', 'مستشار الأعمال', 'FFF5F5', 5, 'كنت زبونًا منتظمًا هنا لعدة أشهر، ولم أكن يومًا خائب الأمل. جودة المنتجات الطازجة واللحوم دائمًا من الدرجة الأولى، والأسعار معقولة للغاية. الموظفون متعاونون وودودون بشكل لا يصدق.', '2024-11-17 05:33:41', '2024-11-17 05:33:41'),
(11, 13, 22, '786b74eaba56184ac2ebc0b2051e9410a2ca7bab.png', 'عمر خالد', 'مهندس', 'F5FFF9', 5, 'يقدم متجر البقالة هذا أفضل مجموعة متنوعة في المدينة. يمكنني دائما العثور على كل ما أحتاجه ، سواء كان ذلك من الضروريات اليومية أو المكونات الخاصة. المتجر منظم جيدا ونظيف. تجربة تسوق رائعة!', '2024-11-17 05:34:14', '2024-11-17 05:34:14'),
(12, 13, 22, '1957a634999b7f7dcd22f39cd8cd1307fd282c57.png', 'فيصل المنصوري', 'أخصائي تكنولوجيا المعلومات', 'FAF5FF', 4, 'أسعار جيدة ومجموعة كبيرة من المنتجات. أجد دائما ما أحتاجه ، لكنني أتمنى أن يكون هناك المزيد من التنوع في قسم الوجبات الخفيفة. بشكل عام ، أنا راض جدا عن الجودة والخدمة.', '2024-11-17 05:34:51', '2024-11-17 05:34:51'),
(13, 11, 17, 'a87acd5dc6f49816086c4cc7c608326698044916.png', 'Sarah Johnson', 'Interior Designer', 'FFEDE4', 5, 'I’ve been a regular shopper here for months, and I am never disappointed. The quality of the fresh produce and meats is always top-notch, and the prices are very reasonable. The staff is incredibly helpful and friendly.', '2024-11-20 05:56:07', '2024-11-24 07:30:27'),
(14, 11, 17, '1204abcabb1beccfc6cf3e2dc379b3e96e9cca98.png', 'Mark Davis', 'Homeowner', 'EAEAEA', 5, 'Good prices and a great selection of products. I always find what I need, but I wish there were more variety in the snacks section. Overall, I’m very satisfied with the quality and service.', '2024-11-20 05:57:01', '2024-11-24 07:31:38'),
(15, 11, 17, '9c5ab5c0607275f65e0475c723d2be4c21d742b2.png', 'Emily Carter', 'Architect', 'E2EEDD', 5, 'Their furniture combines style and durability. It’s a pleasure to work with pieces that are both functional and beautiful', '2024-11-20 05:57:38', '2024-11-24 06:42:24'),
(18, 11, 18, 'af9261fb680a47c3c201321037c52c2ab6e3157e.png', 'سارة جونسون', 'مصمم داخلي', 'FFEDE4', 5, 'لقد كنت أتسوق هنا بشكل منتظم لعدة أشهر، ولم أشعر بخيبة الأمل أبدًا. جودة المنتجات واللحوم الطازجة دائمًا من الدرجة الأولى، والأسعار معقولة جدًا. الموظفون متعاونون وودودون بشكل لا يصدق.', '2024-11-20 06:09:31', '2024-11-24 07:30:42'),
(19, 11, 18, '5f3e37db588299ff84732d6a548e60501fb99291.png', 'مارك ديفيس', 'مالك المنزل', 'C7C5B6', 5, 'أسعار جيدة ومجموعة كبيرة من المنتجات. أجد دائمًا ما أحتاجه، ولكن أتمنى أن يكون هناك المزيد من التنوع في قسم الوجبات الخفيفة. بشكل عام، أنا راضٍ جدًا عن الجودة والخدمة.', '2024-11-20 06:10:14', '2024-11-24 07:31:07'),
(20, 11, 18, '907205a82f3a868decf06d157fc566b6517019d9.png', 'إميلي كارتر', 'مهندس معماري', 'E2EEDD', 5, 'يجمع أثاثهم بين الأناقة والمتانة. إنه لمن دواعي سروري العمل مع قطع عملية وجميلة في نفس الوقت', '2024-11-20 06:10:51', '2024-11-24 06:42:33'),
(22, 12, 19, '247fe9a68503ddc783c783e2789c9f3de7b82d86.png', 'Sarah Johnson', 'Fashion Blogger', 'FFF5F5', 5, 'I absolutely love the unique styles and quality of fabrics. Every outfit I’ve purchased has been a perfect fit, and the designs are always on trend!', '2024-11-21 05:43:09', '2024-11-24 06:38:57'),
(23, 12, 19, '37ba1f0c27b9f314d95031ba7fab872a326d6f42.png', 'Michael Adams', 'Creative Director', 'F5FFF9', 5, 'I was blown away by the variety of styles available. The customer service is top-notch, and the pieces always make me feel confident and stylish!', '2024-11-21 05:43:35', '2024-11-24 06:39:17'),
(24, 12, 19, 'cf6c6aaaeb8e7129012da94068d7be298c245b23.png', 'Emily Clark', 'Entrepreneur', 'FAF5FF', 5, 'The clothes are fabulous and made to last. The only reason I’m giving four stars instead of five is that I’d love to see more color options in some collections!', '2024-11-21 05:43:57', '2024-11-24 06:39:38'),
(26, 12, 20, 'f2faa2a43429ad17e418ca726bb5afe79090226d.png', 'سارة جونسون', 'مدونة أزياء', 'FFF5F5', 5, 'أنا أحب الأساليب الفريدة وجودة الأقمشة. كل قطعة اشتريتها كانت تناسبني تمامًا، والتصاميم دائمًا على الموضة!', '2024-11-21 05:48:15', '2024-11-24 06:39:10'),
(27, 12, 20, '5105521e87ac37a3df86ae494b405f258bb82450.png', 'مايكل آدامز', 'مدير إبداعي', 'F5FFF9', 5, 'لقد أدهشني تنوع الأساليب المتاحة. خدمة العملاء رائعة، والقطع دائمًا تجعلني أشعر بالثقة والأناقة!', '2024-11-21 05:48:54', '2024-11-24 06:39:27'),
(28, 12, 20, '8895c3d2411a77caa856b8b023bab050e37633bf.png', 'إميلي كلارك', 'رائدة أعمال', 'FAF5FF', 5, 'الملابس رائعة ومصممة لتدوم. السبب الوحيد في إعطائي أربع نجوم بدلاً من خمس هو أنني أتمنى رؤية المزيد من خيارات الألوان في بعض المجموعات!', '2024-11-21 05:49:27', '2024-11-24 06:39:49'),
